import*as THREE from'three';import{mesh,FACE,portQuaternion}from'../../modeling/parts.js';import{materials}from'../../core/index.js';import{roundedRect}from'../../core/geometry.js';export{THREE,mesh,FACE,portQuaternion,materials,roundedRect};
export function hole(s,x,y,r){const h=new THREE.Path();h.absarc(x,y,r,0,2*Math.PI,false);s.holes.push(h);}
export function solid(p,s,d,pos,m,n){return mesh(p,new THREE.ExtrudeGeometry(s,{depth:d,bevelEnabled:false,curveSegments:48}),m,pos,n);}
export const box=(p,s,pos,m,n)=>mesh(p,new THREE.BoxGeometry(...s),m,pos,n);
export function ring(p,r,i,d,pos,m,n){const s=new THREE.Shape();s.absarc(0,0,r,0,2*Math.PI,false);hole(s,0,0,i);return solid(p,s,d,pos,m,n);}
export function boardOutline(){const s=new THREE.Shape();s.moveTo(-21,26.5);s.lineTo(21,26.5);s.lineTo(21,-6.7);s.lineTo(20.1,-7.6);s.lineTo(20.1,-12.5);s.lineTo(21,-13.4);s.lineTo(21,-18.2);s.lineTo(19,-19.5);s.lineTo(19,-23.5);s.absarc(16,-23.5,3,0,-Math.PI,true);s.lineTo(13,-19.5);s.lineTo(-13,-19.5);s.lineTo(-13,-23.5);s.absarc(-16,-23.5,3,0,-Math.PI,true);s.lineTo(-19,-19.5);s.lineTo(-21,-18.2);s.lineTo(-21,-13.4);s.lineTo(-20.1,-12.5);s.lineTo(-20.1,-7.6);s.lineTo(-21,-6.7);s.closePath();return s;}
/** Own fixed flex cross-section sweep. Four edges per section and two closed end caps. */
export function ribbon(parent,path,material,name){const p=[],ix=[];for(let k=0;k<path.length;k++){const s=path[k],a=path[Math.max(0,k-1)],b=path[Math.min(path.length-1,k+1)],dy=b.y-a.y,dz=b.z-a.z,l=Math.hypot(dy,dz),t=(s.thickness??.12)/2;for(const[x,v]of[[-s.width/2,-1],[s.width/2,-1],[s.width/2,1],[-s.width/2,1]])p.push((s.x??0)+x,s.y-dz/l*t*v,s.z+dy/l*t*v);}for(let k=0;k<path.length-1;k++)for(let j=0;j<4;j++){const a=k*4+j,b=k*4+(j+1)%4,c=b+4,d=a+4;ix.push(a,b,c,a,c,d);}ix.push(0,2,1,0,3,2);const q=(path.length-1)*4;ix.push(q,q+1,q+2,q,q+2,q+3);let volume=0;for(let k=0;k<ix.length;k+=3){const a=new THREE.Vector3().fromArray(p,ix[k]*3),b=new THREE.Vector3().fromArray(p,ix[k+1]*3),c=new THREE.Vector3().fromArray(p,ix[k+2]*3);volume+=a.dot(b.cross(c));}if(volume<0)for(let k=0;k<ix.length;k+=3)[ix[k+1],ix[k+2]]=[ix[k+2],ix[k+1]];const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(p,3));g.setIndex(ix);g.computeVertexNormals();return mesh(parent,g,material,[0,0,0],name);}
